import{_ as r,o as t,c as n,a2 as e}from"./chunks/framework.B2QVIpOM.js";const g=JSON.parse('{"title":"弘立书院 · 年份未注明 · Foundation Year（小一预备班） · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"isf-academy","school_zh":"弘立书院","school_en":"The ISF Academy","grade":"foundation","year":"unknown","year_label":"年份未注明","type":"interview","title":"弘立书院 · 年份未注明 · Foundation Year（小一预备班） · 面试","anonymous":true,"source_ids":["INT-ISF-FY-HISTORY","INT-ISF-FY-R2-FAMILY"],"rounds":["unknown","r2"]},"headers":[],"relativePath":"reports/isf-academy/foundation/unknown-interview.md","filePath":"reports/isf-academy/foundation/unknown-interview.md"}'),a={name:"reports/isf-academy/foundation/unknown-interview.md"};function s(i,o,p,l,d,c){return t(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="弘立书院-·-年份未注明-·-foundation-year-小一预备班-·-面试" tabindex="-1">弘立书院 · 年份未注明 · Foundation Year（小一预备班） · 面试 <a class="header-anchor" href="#弘立书院-·-年份未注明-·-foundation-year-小一预备班-·-面试" aria-label="Permalink to &quot;弘立书院 · 年份未注明 · Foundation Year（小一预备班） · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/isf-academy">← 返回弘立书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-int-isf-fy-history" tabindex="-1">资料来源：弘立书院小一预备班面经_2025年秋季.pdf；弘立书院考经.pdf <a class="header-anchor" href="#record-int-isf-fy-history" aria-label="Permalink to &quot;资料来源：弘立书院小一预备班面经_2025年秋季.pdf；弘立书院考经.pdf {#record-int-isf-fy-history}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理的往年面试内容</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>学生评估：</strong> 英语、中文</p><p><strong>小组安排与考核内容</strong><br> 历史安排为约20人一组，约45分钟，包含中英双语活动：书写中英文姓名、中英文拼读、数学计算、拼图及叙述故事；完成后可以在旁玩耍。</p><p><strong>另一组历史时长安排</strong><br> 另有历史安排为约20人一组、总计1小时，英语与普通话各约30分钟，后续为亲子会面。不同年份的活动时长可能有所调整。</p><p><strong>观察重点</strong><br> 关注好奇心、探究意愿、陌生环境适应和听从指令的表现。另有往年活动包括听故事回答问题、听音乐做律动，以及按教师指示完成动作，观察反应和大小肌肉发展。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 英语／普通话／广东话</p><p><strong>时长与语言</strong><br> 历史反馈约20分钟，可选择英语、普通话或广东话。</p><p><strong>家庭与照顾安排</strong></p><ul><li>介绍父母、祖父母等家庭背景。</li><li>平日由谁照顾孩子？怎样协助孩子学习？</li><li>家乡在哪里？为什么来香港读书？</li></ul><p><strong>择校与孩子特点</strong></p><ul><li>Why ISF?</li><li>对弘立的印象是什么？对学校有什么改善建议？</li><li>孩子有什么优点和缺点？如何看待孩子在教育方面的优势和劣势？</li></ul></blockquote><h2 id="record-int-isf-fy-r2-family" tabindex="-1">资料来源：弘立书院小一预备班面经_2025年秋季.pdf <a class="header-anchor" href="#record-int-isf-fy-r2-family" aria-label="Permalink to &quot;资料来源：弘立书院小一预备班面经_2025年秋季.pdf {#record-int-isf-fy-r2-family}&quot;">​</a></h2><p><strong>资料类型：</strong> 考后反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>第二轮亲子面试</strong><br> 家长反馈全程约1小时，入场前先由教师核对资料。学生先与教师交流，之后独立完成工作纸；教师在这期间与家长面谈。</p></blockquote><blockquote><p><strong>学生面试：</strong> 语言未注明</p><p><strong>日常交流</strong><br> 先回答一些日常问题，约10分钟。</p><p><strong>图片排序与叙述</strong><br> 第一组为四张卡片：先自行排序并讲述，教师再调整顺序，要求重新讲述。第二组为单张图片，回答“你观察到了什么？”以及“如果你是图中的小朋友，你会怎么办？”</p><p><strong>独立工作纸</strong><br> 约十张，教师先协助理解题意，再让学生独立完成。家长了解到的内容包括连线、分类、排序等数学活动及涂色。完成后举手示意；因家长面谈尚未结束，教师让学生在纸背画画等待。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>教育理念交流</strong><br> 围绕家庭教育理念讨论，家长轮流回答及补充；另有一位教师在旁记录。结束前留有家长提问环节。</p></blockquote><blockquote><p><strong>家长反馈：</strong></p><p><strong>持续参与与等待</strong><br> 家长认为对四岁孩子而言，全程时间较长，担心孩子难以持续坐定。分享时仍在等候录取结果。</p></blockquote>',19)])])}const f=r(a,[["render",s]]);export{g as __pageData,f as default};
